// Bankr test image endpoint.
//
// Serves the PNG image that is referenced by the `image` field in the
// static metadata JSON. Bankr pins the metadata JSON once at launch
// (frozen IPFS CID), but the `image` URL inside that JSON points here
// so the rendered image can be swapped without re-pinning.
//
// To change the image: replace PNG_BYTES_BASE64 below with the new
// image's base64 encoding and push. Vercel auto-deploys.

export const config = {
  runtime: "edge",
};

// 1080x1080 PNG, "AKHIRNYA BISA JUGA KONTOOOOL!!!!!" text on black
const PNG_BYTES_BASE64 = "";

const IMAGE_BYTES = Uint8Array.from(atob(PNG_BYTES_BASE64), (c) => c.charCodeAt(0));

export default function handler(): Response {
  return new Response(IMAGE_BYTES, {
    status: 200,
    headers: {
      "Content-Type": "image/png",
      // 5min edge cache, 1min browser cache — image rarely changes but
      // we want updates to propagate within ~1min on consumer clients
      "Cache-Control": "public, s-maxage=300, max-age=60",
      "Access-Control-Allow-Origin": "*",
      "Content-Length": IMAGE_BYTES.length.toString(),
    },
  });
}